import {ageIncomeData} from './planning-age-income-data.js';
export const ageIncomeDefinitions={ageIncomeSnapshot:{mode:'statistics',title:'Explore a dated cross-section of employment income',fields:[['incomeAgeYear','Reference year in the downloaded snapshot',2024,2022,2024,1]]}};
export function ageIncomeResult(kind,input){
 if(kind!=='ageIncomeSnapshot')throw Error('Unknown age-income view');
 const period=ageIncomeData.years.find(x=>x.year===input.incomeAgeYear),rows=period.rows;
 const withIncome=rows.reduce((s,r)=>s+r.recipients,0),persons=rows.reduce((s,r)=>s+r.persons,0);
 const shared={rowLabel:'Age band',source:ageIncomeData.url,sourceLabel:'Statistics Canada · Table 11-10-0239-01'};
 const money={...shared,unit:'money',tableUnit:'2024 constant CAD per income recipient; annual',unitLabel:'Annual employment income in 2024 constant CAD; zeros excluded'};
 return {metrics:[['Selected income reference year',period.year,'integer'],['Estimated persons in the six age bands',persons,'integer'],['Derived share reporting employment income',withIncome/persons,'percent']],
 note:'Fixed public snapshot released 29 April 2026, reviewed 25 October 2026. Canada; Total - Gender; Employment income. The year control selects observed 2022–2024 cross-sections and never forecasts. All income amounts are annual 2024 constant CAD, with zero incomes excluded from the published means and medians. Income is not take-home pay or a full-time-worker salary quote. Counts and conditional income measures have different denominators. Quality letters are retained from the source: A Excellent, B Very good, C Good, D Acceptable. They are not confidence intervals, and no comparison is declared statistically significant. Different age bands contain different people; no individual career path, causal age effect or future pay increase is estimated.',
 charts:[
  {...money,id:'age-income-mean-median',type:'groupbar',title:'Compare two income summaries within the same age band',seriesNames:['Mean · zeros excluded','Median · zeros excluded'],rows:rows.map(r=>({label:r.label+' · '+r.meanQuality+'/'+r.medianQuality,values:[r.mean,r.median]})),note:'Age bands are disjoint and remain in age order. Letters after each age label are the source quality codes for mean / median, in that order. The value axis begins at zero. These are conditional summaries of people with employment income, not all-person averages, percentile bands or guaranteed annual salaries. The difference between mean and median is not a personal loss or a measure of the full distribution.'},
  {...shared,id:'age-income-counts',type:'stackbar',evidence:'Official counts and a derived remainder',unit:'count',axisTicks:2,unitLabel:'Estimated persons in the selected age band; count in units',tableUnit:'Estimated persons, units',title:'Keep the income-recipient count beside the whole age group',seriesNames:['With non-zero employment income','Remainder of age-band count'],rows:rows.map(r=>({label:r.label+' · '+r.recipientsQuality+'/'+r.personsQuality,values:[r.recipients,r.persons-r.recipients]})),note:'Each full bar equals the published number of persons. Its first part is the published number with employment income; the remainder is subtraction of two rounded estimates. Letters label the source recipient count / all-person count, not a separately assessed quality grade for the remainder. The bar parts are mutually exclusive. These population estimates are not the survey sample sizes, and the six bands exclude overlapping 15+ and 25–54 aggregate rows.'},
  {...shared,id:'age-income-recipient-share',type:'bar',evidence:'Derived from official counts',unit:'percent',unitLabel:'Persons with employment income ÷ persons in the same age band',tableUnit:'Derived ratio of rounded estimated counts',title:'Read the share before applying a recipient’s median to everyone',rows:rows.map(r=>({label:r.label,value:r.recipients/r.persons})),note:'Each ratio is calculated from the two source counts for that exact age, geography, gender and reference year. It is a share reporting employment income over the income reference year, not the Labour Force Survey employment rate, a full-year work rate, a probability of a future job or a share earning above the median. No confidence interval for this derived ratio is supplied.'},
  {...money,id:'age-income-share-median',type:'scatter',labelLeaders:true,evidence:'Official median and a derived count ratio',pointLabelHeader:'Age band / median quality',pointContext:'Each hollow point is one observed age-band estimate. Thin guides connect displaced age labels to their points. Both coordinates use the same selected reference year.',xUnit:'percent',xLabel:'With income / all in band (%)',yLabel:'Recipient median, 2024 CAD',title:'Inspect the recipient share and conditional median together',rows:rows.map(r=>({label:r.label+' · '+r.medianQuality,x:r.recipients/r.persons,value:r.median,annotate:true})),note:'One point represents one age band in the selected year. Its horizontal position uses that band’s derived recipient share; its vertical position uses the published median excluding zeros. Labels retain the median’s source quality letter. These are two different measures at a common group grain, not a fitted relationship or an individual earnings path. No line connects one age estimate to the next, and no causal or predictive relationship is calculated.'}
 ]};
}
